-- SINH TỰ ĐỘNG — KHÔNG SỬA TAY.
-- Nguồn: backend/app/semantic/feature_spec.py + backend/scripts/generate_dbt_models.py
-- Sinh lại:  cd backend && python -m scripts.generate_dbt_models
--
-- Bản nháp của feature.vinfast_transaction. Ba CTE vì ba nguồn có GRAIN KHÁC
-- NHAU: đơn hàng, đơn mua xe, bản ghi bàn giao. Join chung một lượt thì nhân dòng.
-- 186 cột đơn hàng + 7 cột người mua + 9 cột sở hữu.
--
-- alias trùng tên bảng gold để `parity_check --source dbt_work` so thẳng candidate với
-- baseline mà không cần bảng ánh xạ tên. Schema thì vẫn là dbt_work — dbt không có
-- quyền DDL trên feature.*, việc ghi sang đó là của publish_gold.py.
{{ config(alias='vinfast_transaction') }}

with don_hang as (
  select
    s.customer_id,
    s.snapshot_date,
    (s.snapshot_date - min(o.updated_date) filter (where o.status = 'completed')) as days_since_first_completed_txn_days_daily,
    (s.snapshot_date - min(o.updated_date) filter (where o.status = 'completed')) as days_since_first_completed_txn_days_l12m,
    (s.snapshot_date - min(o.updated_date) filter (where o.status = 'completed')) as days_since_first_completed_txn_days_l1m,
    (s.snapshot_date - min(o.updated_date) filter (where o.status = 'completed')) as days_since_first_completed_txn_days_l1w,
    (s.snapshot_date - min(o.updated_date) filter (where o.status = 'completed')) as days_since_first_completed_txn_days_l2w,
    (s.snapshot_date - min(o.updated_date) filter (where o.status = 'completed')) as days_since_first_completed_txn_days_l3m,
    (s.snapshot_date - min(o.updated_date) filter (where o.status = 'completed')) as days_since_first_completed_txn_days_l6m,
    (s.snapshot_date - max(o.updated_date) filter (where o.status = 'completed')) as days_since_last_completed_txn_days_daily,
    (s.snapshot_date - max(o.updated_date) filter (where o.status = 'completed')) as days_since_last_completed_txn_days_l12m,
    (s.snapshot_date - max(o.updated_date) filter (where o.status = 'completed')) as days_since_last_completed_txn_days_l1m,
    (s.snapshot_date - max(o.updated_date) filter (where o.status = 'completed')) as days_since_last_completed_txn_days_l1w,
    (s.snapshot_date - max(o.updated_date) filter (where o.status = 'completed')) as days_since_last_completed_txn_days_l2w,
    (s.snapshot_date - max(o.updated_date) filter (where o.status = 'completed')) as days_since_last_completed_txn_days_l3m,
    (s.snapshot_date - max(o.updated_date) filter (where o.status = 'completed')) as days_since_last_completed_txn_days_l6m,
    case when (coalesce(sum(o.paid_amount) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'cancelled' and o.order_type = 'accessories'), 0)) <> 0 then round(((coalesce(sum(o.paid_amount) filter (where o.created_date >= s.snapshot_date - 29 and o.status = 'cancelled' and o.order_type = 'accessories'), 0))::float8 / (coalesce(sum(o.paid_amount) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'cancelled' and o.order_type = 'accessories'), 0))::float8) * 10000) / 10000 end as txn_accessories_canceled_amount_sum_l1m_vs_l12m,
    case when (coalesce(sum(o.paid_amount) filter (where o.created_date >= s.snapshot_date - 89 and o.status = 'cancelled' and o.order_type = 'accessories'), 0)) <> 0 then round(((coalesce(sum(o.paid_amount) filter (where o.created_date >= s.snapshot_date - 29 and o.status = 'cancelled' and o.order_type = 'accessories'), 0))::float8 / (coalesce(sum(o.paid_amount) filter (where o.created_date >= s.snapshot_date - 89 and o.status = 'cancelled' and o.order_type = 'accessories'), 0))::float8) * 10000) / 10000 end as txn_accessories_canceled_amount_sum_l1m_vs_l3m,
    case when (coalesce(sum(o.paid_amount) filter (where o.created_date >= s.snapshot_date - 179 and o.status = 'cancelled' and o.order_type = 'accessories'), 0)) <> 0 then round(((coalesce(sum(o.paid_amount) filter (where o.created_date >= s.snapshot_date - 29 and o.status = 'cancelled' and o.order_type = 'accessories'), 0))::float8 / (coalesce(sum(o.paid_amount) filter (where o.created_date >= s.snapshot_date - 179 and o.status = 'cancelled' and o.order_type = 'accessories'), 0))::float8) * 10000) / 10000 end as txn_accessories_canceled_amount_sum_l1m_vs_l6m,
    case when (coalesce(sum(o.paid_amount) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'cancelled' and o.order_type = 'accessories'), 0)) <> 0 then round(((coalesce(sum(o.paid_amount) filter (where o.created_date >= s.snapshot_date - 89 and o.status = 'cancelled' and o.order_type = 'accessories'), 0))::float8 / (coalesce(sum(o.paid_amount) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'cancelled' and o.order_type = 'accessories'), 0))::float8) * 10000) / 10000 end as txn_accessories_canceled_amount_sum_l3m_vs_l12m,
    case when (count(*) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'cancelled' and o.order_type = 'accessories')) <> 0 then round(((count(*) filter (where o.created_date >= s.snapshot_date - 29 and o.status = 'cancelled' and o.order_type = 'accessories'))::float8 / (count(*) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'cancelled' and o.order_type = 'accessories'))::float8) * 10000) / 10000 end as txn_accessories_canceled_count_l1m_vs_l12m,
    case when (count(*) filter (where o.created_date >= s.snapshot_date - 89 and o.status = 'cancelled' and o.order_type = 'accessories')) <> 0 then round(((count(*) filter (where o.created_date >= s.snapshot_date - 29 and o.status = 'cancelled' and o.order_type = 'accessories'))::float8 / (count(*) filter (where o.created_date >= s.snapshot_date - 89 and o.status = 'cancelled' and o.order_type = 'accessories'))::float8) * 10000) / 10000 end as txn_accessories_canceled_count_l1m_vs_l3m,
    case when (count(*) filter (where o.created_date >= s.snapshot_date - 179 and o.status = 'cancelled' and o.order_type = 'accessories')) <> 0 then round(((count(*) filter (where o.created_date >= s.snapshot_date - 29 and o.status = 'cancelled' and o.order_type = 'accessories'))::float8 / (count(*) filter (where o.created_date >= s.snapshot_date - 179 and o.status = 'cancelled' and o.order_type = 'accessories'))::float8) * 10000) / 10000 end as txn_accessories_canceled_count_l1m_vs_l6m,
    case when (count(*) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'cancelled' and o.order_type = 'accessories')) <> 0 then round(((count(*) filter (where o.created_date >= s.snapshot_date - 89 and o.status = 'cancelled' and o.order_type = 'accessories'))::float8 / (count(*) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'cancelled' and o.order_type = 'accessories'))::float8) * 10000) / 10000 end as txn_accessories_canceled_count_l3m_vs_l12m,
    case when (coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'cancelled' and o.order_type = 'accessories'), 0)) <> 0 then round(((coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 29 and o.status = 'cancelled' and o.order_type = 'accessories'), 0))::float8 / (coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'cancelled' and o.order_type = 'accessories'), 0))::float8) * 10000) / 10000 end as txn_accessories_canceled_price_sum_l1m_vs_l12m,
    case when (coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 89 and o.status = 'cancelled' and o.order_type = 'accessories'), 0)) <> 0 then round(((coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 29 and o.status = 'cancelled' and o.order_type = 'accessories'), 0))::float8 / (coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 89 and o.status = 'cancelled' and o.order_type = 'accessories'), 0))::float8) * 10000) / 10000 end as txn_accessories_canceled_price_sum_l1m_vs_l3m,
    case when (coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 179 and o.status = 'cancelled' and o.order_type = 'accessories'), 0)) <> 0 then round(((coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 29 and o.status = 'cancelled' and o.order_type = 'accessories'), 0))::float8 / (coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 179 and o.status = 'cancelled' and o.order_type = 'accessories'), 0))::float8) * 10000) / 10000 end as txn_accessories_canceled_price_sum_l1m_vs_l6m,
    case when (coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'cancelled' and o.order_type = 'accessories'), 0)) <> 0 then round(((coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 89 and o.status = 'cancelled' and o.order_type = 'accessories'), 0))::float8 / (coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'cancelled' and o.order_type = 'accessories'), 0))::float8) * 10000) / 10000 end as txn_accessories_canceled_price_sum_l3m_vs_l12m,
    case when (coalesce(sum(o.paid_amount) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'completed' and o.order_type = 'accessories'), 0)) <> 0 then round(((coalesce(sum(o.paid_amount) filter (where o.created_date >= s.snapshot_date - 29 and o.status = 'completed' and o.order_type = 'accessories'), 0))::float8 / (coalesce(sum(o.paid_amount) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'completed' and o.order_type = 'accessories'), 0))::float8) * 10000) / 10000 end as txn_accessories_completed_amount_sum_l1m_vs_l12m,
    case when (coalesce(sum(o.paid_amount) filter (where o.created_date >= s.snapshot_date - 89 and o.status = 'completed' and o.order_type = 'accessories'), 0)) <> 0 then round(((coalesce(sum(o.paid_amount) filter (where o.created_date >= s.snapshot_date - 29 and o.status = 'completed' and o.order_type = 'accessories'), 0))::float8 / (coalesce(sum(o.paid_amount) filter (where o.created_date >= s.snapshot_date - 89 and o.status = 'completed' and o.order_type = 'accessories'), 0))::float8) * 10000) / 10000 end as txn_accessories_completed_amount_sum_l1m_vs_l3m,
    case when (coalesce(sum(o.paid_amount) filter (where o.created_date >= s.snapshot_date - 179 and o.status = 'completed' and o.order_type = 'accessories'), 0)) <> 0 then round(((coalesce(sum(o.paid_amount) filter (where o.created_date >= s.snapshot_date - 29 and o.status = 'completed' and o.order_type = 'accessories'), 0))::float8 / (coalesce(sum(o.paid_amount) filter (where o.created_date >= s.snapshot_date - 179 and o.status = 'completed' and o.order_type = 'accessories'), 0))::float8) * 10000) / 10000 end as txn_accessories_completed_amount_sum_l1m_vs_l6m,
    case when (coalesce(sum(o.paid_amount) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'completed' and o.order_type = 'accessories'), 0)) <> 0 then round(((coalesce(sum(o.paid_amount) filter (where o.created_date >= s.snapshot_date - 89 and o.status = 'completed' and o.order_type = 'accessories'), 0))::float8 / (coalesce(sum(o.paid_amount) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'completed' and o.order_type = 'accessories'), 0))::float8) * 10000) / 10000 end as txn_accessories_completed_amount_sum_l3m_vs_l12m,
    count(*) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'completed' and o.order_type = 'accessories') as txn_accessories_completed_count_l12m,
    case when (count(*) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'completed' and o.order_type = 'accessories')) <> 0 then round(((count(*) filter (where o.created_date >= s.snapshot_date - 29 and o.status = 'completed' and o.order_type = 'accessories'))::float8 / (count(*) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'completed' and o.order_type = 'accessories'))::float8) * 10000) / 10000 end as txn_accessories_completed_count_l1m_vs_l12m,
    case when (count(*) filter (where o.created_date >= s.snapshot_date - 89 and o.status = 'completed' and o.order_type = 'accessories')) <> 0 then round(((count(*) filter (where o.created_date >= s.snapshot_date - 29 and o.status = 'completed' and o.order_type = 'accessories'))::float8 / (count(*) filter (where o.created_date >= s.snapshot_date - 89 and o.status = 'completed' and o.order_type = 'accessories'))::float8) * 10000) / 10000 end as txn_accessories_completed_count_l1m_vs_l3m,
    case when (count(*) filter (where o.created_date >= s.snapshot_date - 179 and o.status = 'completed' and o.order_type = 'accessories')) <> 0 then round(((count(*) filter (where o.created_date >= s.snapshot_date - 29 and o.status = 'completed' and o.order_type = 'accessories'))::float8 / (count(*) filter (where o.created_date >= s.snapshot_date - 179 and o.status = 'completed' and o.order_type = 'accessories'))::float8) * 10000) / 10000 end as txn_accessories_completed_count_l1m_vs_l6m,
    case when (count(*) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'completed' and o.order_type = 'accessories')) <> 0 then round(((count(*) filter (where o.created_date >= s.snapshot_date - 89 and o.status = 'completed' and o.order_type = 'accessories'))::float8 / (count(*) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'completed' and o.order_type = 'accessories'))::float8) * 10000) / 10000 end as txn_accessories_completed_count_l3m_vs_l12m,
    coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'completed' and o.order_type = 'accessories'), 0) as txn_accessories_completed_price_sum_l12m,
    case when (coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'completed' and o.order_type = 'accessories'), 0)) <> 0 then round(((coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 29 and o.status = 'completed' and o.order_type = 'accessories'), 0))::float8 / (coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'completed' and o.order_type = 'accessories'), 0))::float8) * 10000) / 10000 end as txn_accessories_completed_price_sum_l1m_vs_l12m,
    case when (coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 89 and o.status = 'completed' and o.order_type = 'accessories'), 0)) <> 0 then round(((coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 29 and o.status = 'completed' and o.order_type = 'accessories'), 0))::float8 / (coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 89 and o.status = 'completed' and o.order_type = 'accessories'), 0))::float8) * 10000) / 10000 end as txn_accessories_completed_price_sum_l1m_vs_l3m,
    case when (coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 179 and o.status = 'completed' and o.order_type = 'accessories'), 0)) <> 0 then round(((coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 29 and o.status = 'completed' and o.order_type = 'accessories'), 0))::float8 / (coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 179 and o.status = 'completed' and o.order_type = 'accessories'), 0))::float8) * 10000) / 10000 end as txn_accessories_completed_price_sum_l1m_vs_l6m,
    case when (coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'completed' and o.order_type = 'accessories'), 0)) <> 0 then round(((coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 89 and o.status = 'completed' and o.order_type = 'accessories'), 0))::float8 / (coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'completed' and o.order_type = 'accessories'), 0))::float8) * 10000) / 10000 end as txn_accessories_completed_price_sum_l3m_vs_l12m,
    count(distinct o.created_date) filter (where o.created_date >= s.snapshot_date - 0 and o.status = 'cancelled') as txn_canceled_active_day_count_daily,
    count(distinct o.created_date) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'cancelled') as txn_canceled_active_day_count_l12m,
