    case when (coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'completed' and o.order_type = 'work_order'), 0)) <> 0 then round(((coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 29 and o.status = 'completed' and o.order_type = 'work_order'), 0))::float8 / (coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'completed' and o.order_type = 'work_order'), 0))::float8) * 10000) / 10000 end as txn_wo_completed_price_sum_l1m_vs_l12m,
    case when (coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 89 and o.status = 'completed' and o.order_type = 'work_order'), 0)) <> 0 then round(((coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 29 and o.status = 'completed' and o.order_type = 'work_order'), 0))::float8 / (coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 89 and o.status = 'completed' and o.order_type = 'work_order'), 0))::float8) * 10000) / 10000 end as txn_wo_completed_price_sum_l1m_vs_l3m,
    case when (coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 179 and o.status = 'completed' and o.order_type = 'work_order'), 0)) <> 0 then round(((coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 29 and o.status = 'completed' and o.order_type = 'work_order'), 0))::float8 / (coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 179 and o.status = 'completed' and o.order_type = 'work_order'), 0))::float8) * 10000) / 10000 end as txn_wo_completed_price_sum_l1m_vs_l6m,
    case when (coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'completed' and o.order_type = 'work_order'), 0)) <> 0 then round(((coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 89 and o.status = 'completed' and o.order_type = 'work_order'), 0))::float8 / (coalesce(sum(o.list_price) filter (where o.created_date >= s.snapshot_date - 364 and o.status = 'completed' and o.order_type = 'work_order'), 0))::float8) * 10000) / 10000 end as txn_wo_completed_price_sum_l3m_vs_l12m
  from {{ ref('silver_customer_snapshot') }} s
  left join {{ ref('silver_vinfast_order_state') }} o
         on o.customer_id = s.customer_id
        and o.snapshot_date = s.snapshot_date
  group by s.customer_id, s.snapshot_date
),

nguoi_mua as (
  select
    s.customer_id,
    s.snapshot_date,
    min(p.completed_date) as first_vehicle_purchase_date,
    coalesce(bool_or(p.order_id is not null), false) as is_vehicle_buyer,
    count(*) filter (where p.order_id is not null and true) as vehicle_purchase_completed_count_all,
    count(*) filter (where p.order_id is not null and p.completed_date >= s.snapshot_date - 364) as vehicle_purchase_completed_count_l12m,
    count(*) filter (where p.order_id is not null and p.completed_date >= s.snapshot_date - 29) as vehicle_purchase_completed_count_l1m,
    count(*) filter (where p.order_id is not null and p.completed_date >= s.snapshot_date - 89) as vehicle_purchase_completed_count_l3m,
    count(*) filter (where p.order_id is not null and p.completed_date >= s.snapshot_date - 179) as vehicle_purchase_completed_count_l6m
  from {{ ref('silver_customer_snapshot') }} s
  left join {{ ref('silver_vehicle_purchase') }} p
         on p.customer_id = s.customer_id
        and p.snapshot_date = s.snapshot_date
  group by s.customer_id, s.snapshot_date
),

so_huu as (
  select
    s.customer_id,
    s.snapshot_date,
    (s.snapshot_date - max(h.handed_over_date) filter (where h.is_handed_over)) as days_since_last_vehicle_handover,
    min(h.handed_over_date) filter (where h.is_handed_over) as first_vehicle_handover_date,
    coalesce(bool_or(h.is_pending), false) as is_vehicle_handover_scheduled,
    coalesce(bool_or(h.is_owned), false) as is_vehicle_owner,
    count(distinct h.vehicle_id) filter (where h.is_handed_over and true) as vehicle_delivered_count_all,
    count(distinct h.vehicle_id) filter (where h.is_handed_over and h.handed_over_date >= s.snapshot_date - 364) as vehicle_delivered_count_l12m,
    count(distinct h.vehicle_id) filter (where h.is_handed_over and h.handed_over_date >= s.snapshot_date - 29) as vehicle_delivered_count_l1m,
    count(distinct h.vehicle_id) filter (where h.is_handed_over and h.handed_over_date >= s.snapshot_date - 89) as vehicle_delivered_count_l3m,
    count(distinct h.vehicle_id) filter (where h.is_handed_over and h.handed_over_date >= s.snapshot_date - 179) as vehicle_delivered_count_l6m
  from {{ ref('silver_customer_snapshot') }} s
  left join {{ ref('silver_vehicle_ownership') }} h
         on h.customer_id = s.customer_id
        and h.snapshot_date = s.snapshot_date
  group by s.customer_id, s.snapshot_date
)

